		strings.Contains(statement, "OBJECT_OVERWRITE") {
		snapshots++
	}
}
if snapshots != 1 {
	t.Fatalf("controller policy grants the KV snapshot prefix %d times", snapshots)
}
channel := 0
for _, statement := range statements {
	if strings.Contains(statement, "target.bucket.name='gru-1-head', target.object.name='releases/*', request.permission='OBJECT_READ'}") ||
		strings.Contains(statement, "target.bucket.name='gru-1-head', target.object.name='releases/orchestrator/status.json', any {request.permission='OBJECT_CREATE', request.permission='OBJECT_OVERWRITE'}}") {
		channel++
	}
}
if channel != 2 {
	t.Fatalf("controller policy grants the release channel %d times, want its read and its status write", channel)
}
var profile struct {
	Env map[string]string `json:"env"`
}
wire, err := os.ReadFile(filepath.Join(root, "terrabase-gru-1-profile.json"))
