cf_do.text:
func (c Cloudflare) do(ctx context.Context, method, path string, body, result any) error {
	var payload io.Reader
	if body != nil {
		wire, err := json.Marshal(body)
		if err != nil {
			return err
		}
		payload = bytes.NewReader(wire)
	}
	request, err := http.NewRequestWithContext(ctx, method, c.BaseURL+path, payload)
	if err != nil {
		return err
	}
	if c.Token != "" {
		request.Header.Set("Authorization", "Bearer "+c.Token)
	}
	request.Header.Set("Content-Type", "application/json")
	client := c.HTTP
	if client == nil {
		client = &http.Client{Timeout: 30 * time.Second}
	}
	response, err := client.Do(request)
	if err != nil {
		return fmt.Errorf("Cloudflare %s %s: %w", method, path, err)
	}
	defer response.Body.Close()
	var envelope struct {
		Success bool           `json:"success"`
		Errors  []any          `json:"errors"`
		Result  jsontext.Value `json:"result"`
	}
	if err := json.UnmarshalRead(io.LimitReader(response.Body, 1<<20), &envelope); err != nil {
		return fmt.Errorf("Cloudflare %s %s: %w", method, path, &cloudflareError{Status: response.StatusCode, Detail: err.Error()})
	}
	if !envelope.Success || response.StatusCode/100 != 2 {
		var codes []int
		for _, e := range envelope.Errors {
			if code, ok := field(e, "code").(float64); ok {
				codes = append(codes, int(code))
			}
		}
		return fmt.Errorf("Cloudflare %s %s: %w", method, path, &cloudflareError{response.StatusCode, fmt.Sprint(envelope.Errors), codes})
	}
	if result == nil {
		return nil
	}
	return json.Unmarshal(envelope.Result, result)
}

cf_lookup.text:
func (c Cloudflare) OriginIPs(ctx context.Context) ([]string, error) {
	var ips struct {
		IPv4 []string `json:"ipv4_cidrs"`
	}
	if err := c.do(ctx, http.MethodGet, "/ips", nil, &ips); err != nil {
		return nil, err
	}
	if len(ips.IPv4) == 0 || len(ips.IPv4) > 50 {
		return nil, fmt.Errorf("Cloudflare publishes %d IPv4 ranges, want 1 to 50", len(ips.IPv4))
	}
	for i, cidr := range ips.IPv4 {
		prefix, err := netip.ParsePrefix(cidr)
		if err != nil || !prefix.Addr().Is4() || prefix != prefix.Masked() || prefix.Bits() < 8 || !prefix.Addr().IsGlobalUnicast() || prefix.Addr().IsPrivate() {
			return nil, fmt.Errorf("Cloudflare publishes an unusable IPv4 range %q", cidr)
		}
		ips.IPv4[i] = prefix.String()
	}
	slices.Sort(ips.IPv4)
	return slices.Compact(ips.IPv4), nil
}

func (c Cloudflare) zoneID(ctx context.Context) (string, error) {
	var zones []struct {
		ID   string `json:"id"`
		Name string `json:"name"`
	}
	if err := c.do(ctx, http.MethodGet, "/zones?name="+url.QueryEscape(Zone), nil, &zones); err != nil {
		return "", err
	}
	if len(zones) != 1 || zones[0].Name != Zone || zones[0].ID == "" {
		return "", fmt.Errorf("Cloudflare token sees %d zones named %s, want 1", len(zones), Zone)
	}
	return zones[0].ID, nil
}

cf_strict.text:
func (c Cloudflare) checkStrictTLS(ctx context.Context, entry string, want configRule) error {
	var ruleset struct {
		Rules []configRule `json:"rules"`
	}
	if err := c.do(ctx, http.MethodGet, entry, nil, &ruleset); err != nil {
		return err
	}
	count := 0
	for _, r := range ruleset.Rules {
		if r.Ref == want.Ref {
			count++
		}
	}
	i := slices.IndexFunc(ruleset.Rules, func(r configRule) bool { return r.Ref == want.Ref })
	if count != 1 || !want.same(ruleset.Rules[i]) || !strictTail(ruleset.Rules, i) {
		return fmt.Errorf("Cloudflare rule %s must be uniquely enabled with SSL Full (strict) at the end of the configuration ruleset", want.Ref)
	}
	return nil

cf_edge.text:
func (c Cloudflare) edgeSteps(ctx context.Context, names []string, address netip.Addr, cell string, originPull OriginPull) ([]step, error) {
	if !address.Is4() || !address.IsGlobalUnicast() || address.IsPrivate() {
		return nil, fmt.Errorf("%s is not a public IPv4 address", address)
	}
	if err := originPull.Validate(); err != nil {
		return nil, err
	}
	zone, err := c.zoneID(ctx)
	if err != nil {
		return nil, err
	}
	var steps []step
	quoted := make([]string, len(names))
	for i, name := range names {
		if !strings.HasSuffix(name, "."+Zone) {
			return nil, fmt.Errorf("%s is outside zone %s", name, Zone)
		}
		quoted[i] = `"` + name + `"`
	}
	aopEnabled, err := c.originPullState(ctx, zone, names, originPull, false)
	if err != nil {
		return nil, err
	}
	strict := configRule{Ref: "ts-orch-" + cell + "-api-ssl-strict", Description: cell + " public API: Full (strict) to the origin",
		Expression: "(http.host in {" + strings.Join(quoted, " ") + "})", Action: "set_config",
		Parameters: map[string]any{"ssl": "strict"}, Enabled: true}
	entry := "/zones/" + zone + "/rulesets/phases/http_config_settings/entrypoint"
	var ruleset struct {
		ID    string       `json:"id"`
		Rules []configRule `json:"rules"`
	}
	err = c.do(ctx, http.MethodGet, entry, nil, &ruleset)
	if cf, ok := errors.AsType[*cloudflareError](err); ok && cf.Status == http.StatusNotFound {
		err, ruleset.ID = nil, ""
	}
	if err != nil {
		return nil, err
	}
	what := fmt.Sprintf("set SSL Full (strict) for %s (configuration rule %s)", strings.Join(names, ", "), strict.Ref)
	current := slices.IndexFunc(ruleset.Rules, func(r configRule) bool { return r.Ref == strict.Ref })
	for i, r := range ruleset.Rules {
		if r.Ref == strict.Ref && i != current {
			return nil, fmt.Errorf("Cloudflare configuration rule %s is duplicated; resolve it by hand", strict.Ref)
		}
	}
	writeStrict := func(ctx context.Context, method, path string, body any) error {
		if err := c.do(ctx, method, path, body, nil); err != nil {
			return err
		}
		return c.checkStrictTLS(ctx, entry, strict)
	}
	switch {
	case ruleset.ID == "":
		steps = append(steps, step{what, func(ctx context.Context) error {
			return writeStrict(ctx, http.MethodPut, entry, map[string]any{"rules": []configRule{strict}})
		}})
	case current < 0:
		steps = append(steps, step{what, func(ctx context.Context) error {
			return writeStrict(ctx, http.MethodPost, "/zones/"+zone+"/rulesets/"+ruleset.ID+"/rules", strict)
		}})
	case !strict.same(ruleset.Rules[current]) || !strictTail(ruleset.Rules, current):
		id := ruleset.Rules[current].ID
		steps = append(steps, step{what, func(ctx context.Context) error {
			// Cloudflare's documented empty after position moves the rule last.
			body := struct {
				configRule
				Position map[string]string `json:"position"`
			}{strict, map[string]string{"after": ""}}
			return writeStrict(ctx, http.MethodPatch, "/zones/"+zone+"/rulesets/"+ruleset.ID+"/rules/"+id, body)
		}})
	}
	if !aopEnabled {
		steps = append(steps, step{"enable custom zone Authenticated Origin Pulls", func(ctx context.Context) error {
			if err := c.do(ctx, http.MethodPut, "/zones/"+zone+"/origin_tls_client_auth/settings", map[string]bool{"enabled": true}, nil); err != nil {
				return err
			}
			_, err := c.originPullState(ctx, zone, names, originPull, true)
			return err
		}})
	}
	for _, name := range names {
		var records []record
		if err := c.do(ctx, http.MethodGet, "/zones/"+zone+"/dns_records?name="+url.QueryEscape(name), nil, &records); err != nil {
			return nil, err
		}
		want := record{Type: "A", Name: name, Content: address.String(), Proxied: true, TTL: 1}
		method, path, what := http.MethodPost, "/zones/"+zone+"/dns_records", fmt.Sprintf("create A %s %s (proxied)", name, want.Content)
		switch {
		case len(records) == 0:
		case len(records) == 1 && records[0].Type == "A" && records[0].Name == name:
			if records[0].Content == want.Content && records[0].Proxied {
				continue
			}
			method, path = http.MethodPut, path+"/"+records[0].ID
			what = fmt.Sprintf("update A %s %s (proxied %t) -> %s (proxied)", name, records[0].Content, records[0].Proxied, want.Content)
		default:
			return nil, fmt.Errorf("%s already holds %d records; resolve them by hand", name, len(records))
		}
		steps = append(steps, step{what, func(ctx context.Context) error {
			if _, err := c.originPullState(ctx, zone, names, originPull, true); err != nil {
				return err
			}
			if err := c.checkStrictTLS(ctx, entry, strict); err != nil {
				return err
			}
			return c.do(ctx, method, path, want, nil)
		}})
	}
	return steps, nil
}

// OriginCertificate asks Cloudflare's Origin CA to sign a certificate
// request for hostnames, valid for 15 years, and returns its PEM and ID.
func (c Cloudflare) OriginCertificate(ctx context.Context, csrPEM []byte, hostnames []string) (certificate []byte, id string, err error) {
	var issued struct {
		ID          string `json:"id"`
		Certificate string `json:"certificate"`
	}
	err = c.do(ctx, http.MethodPost, "/certificates", map[string]any{"hostnames": hostnames, "requested_validity": originValidityDays,
		"request_type": "origin-rsa", "csr": string(csrPEM)}, &issued)
	return []byte(issued.Certificate), issued.ID, err
}

origin_pull.text:
// Validate rejects missing configuration, unsafe IDs, and shared or unusable CAs.
func (o OriginPull) Validate() error {
	_, err := o.root()
	return err
}

func (o OriginPull) root() (*x509.Certificate, error) {
	if o.CertificateID == "" || strings.Trim(o.CertificateID, "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-") != "" {
		return nil, errors.New("public_api.origin_pull.certificate_id must contain only letters, digits and hyphens and be nonempty")
	}
	if err := validCA(o.CACertificate); err != nil {
		return nil, fmt.Errorf("public_api.origin_pull.ca_certificate: %w", err)
	}
	block, _ := pem.Decode([]byte(o.CACertificate))
	root, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, err
	}
	sharedBlock, _ := pem.Decode([]byte(originPullCA))
	if sharedBlock == nil {
		return nil, errors.New("shared Cloudflare origin pull CA denylist is unavailable")
	}
	shared, err := x509.ParseCertificate(sharedBlock.Bytes)
	if err != nil {
		return nil, err
	}
	if bytes.Equal(root.RawSubjectPublicKeyInfo, shared.RawSubjectPublicKeyInfo) {
		return nil, errors.New("public_api.origin_pull.ca_certificate must not trust Cloudflare's shared origin pull CA")
	}
	now := time.Now()
	if !root.BasicConstraintsValid || root.KeyUsage&x509.KeyUsageCertSign == 0 ||
		!bytes.Equal(root.RawSubject, root.RawIssuer) || root.CheckSignatureFrom(root) != nil ||
		now.Before(root.NotBefore) || !now.Before(root.NotAfter) {
		return nil, errors.New("public_api.origin_pull.ca_certificate must be a currently valid self-signed signing CA")
	}
	return root, nil
}

// hostnameNotFound is Cloudflare's error code for a hostname without an
// origin pull association.
const hostnameNotFound = 1553

type originPullCertificate struct {
	ID          string `json:"id"`
	Certificate string `json:"certificate"`
	Status      string `json:"status"`
}

// originPullState checks the effective zone certificate and target hostname
// associations. Multiple active certificates do not identify the deployed one.
func (c Cloudflare) originPullState(ctx context.Context, zone string, names []string, o OriginPull, requireEnabled bool) (bool, error) {
	root, err := o.root()
	if err != nil {
		return false, err
	}
	path := "/zones/" + zone + "/origin_tls_client_auth"
	var certificates []originPullCertificate
	if err := c.do(ctx, http.MethodGet, path, nil, &certificates); err != nil {
		return false, err
	}
	if len(certificates) != 1 || certificates[0].ID != o.CertificateID || certificates[0].Status != "active" {
		return false, fmt.Errorf("zone origin pulls require exactly one certificate, reviewed ID %s with status active", o.CertificateID)
	}
	block, rest := pem.Decode([]byte(certificates[0].Certificate))
	if block == nil || block.Type != "CERTIFICATE" || len(bytes.TrimSpace(rest)) != 0 {
		return false, errors.New("zone origin pull client must be one PEM leaf certificate")
	}
	leaf, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return false, fmt.Errorf("zone origin pull client certificate: %w", err)
	}
	if leaf.IsCA || !slices.Contains(leaf.ExtKeyUsage, x509.ExtKeyUsageClientAuth) {
		return false, errors.New("zone origin pull client must be a non-CA leaf with explicit client auth usage")
	}
	if err := leaf.CheckSignatureFrom(root); err != nil {
		return false, fmt.Errorf("zone origin pull client is not directly signed by the reviewed CA: %w", err)
	}
	roots := x509.NewCertPool()
	roots.AddCert(root)
	if _, err := leaf.Verify(x509.VerifyOptions{Roots: roots, KeyUsages: []x509.ExtKeyUsage{x509.ExtKeyUsageClientAuth}}); err != nil {
		return false, fmt.Errorf("zone origin pull client certificate: %w", err)
	}
	for _, name := range names {
		var association struct {
			Hostname string         `json:"hostname"`
			Enabled  jsontext.Value `json:"enabled"`
		}
		// The supported GET is per hostname; collection /hostnames is PUT only.
		// Cloudflare stores no association without a certificate (PUT fails
		// with 1404), so 404 with code 1553 is the absent state and zone AOP
		// applies; verified live 2026-10-05. A successful explicit null also
		// voids it. Every other error fails closed.
		err := c.do(ctx, http.MethodGet, path+"/hostnames/"+url.PathEscape(name), nil, &association)
		var cf *cloudflareError
		if errors.As(err, &cf) && cf.Status == http.StatusNotFound && slices.Contains(cf.Codes, hostnameNotFound) {
			continue
		}
		if err != nil {
			return false, fmt.Errorf("cannot verify origin pull override for %s: %w", name, err)
		}
		if association.Hostname != name || string(association.Enabled) != "null" {
			return false, fmt.Errorf("origin pull hostname override for %s must be explicitly voided (enabled null) before publishing DNS", name)
		}
	}
	var settings struct {
		Enabled *bool `json:"enabled"`
	}
	if err := c.do(ctx, http.MethodGet, path+"/settings", nil, &settings); err != nil {
		return false, err
	}
	if settings.Enabled == nil || requireEnabled && !*settings.Enabled {
		return false, errors.New("custom zone origin pulls must read back enabled")
	}
	return *settings.Enabled, nil
}

sdkcli_parse.text:
// Client serves commands for one region through the shared rate-limited factory.
type Client struct {
	factory *ociclient.Factory
	// endpoint overrides every service host; tests point it at a fake.
	endpoint string
}

// NewClient shares the authenticated provider, rate limits and retry policy of factory.
func NewClient(factory *ociclient.Factory, endpoint string) *Client {
	return &Client{factory: factory, endpoint: endpoint}
}

// Factory is the shared rate-limited factory this client reads through.
func (c *Client) Factory() *ociclient.Factory { return c.factory }

func (c *Client) pin(client *common.BaseClient) {
	client.HTTPClient = strictResponses{next: client.HTTPClient}
	ociclient.ConfigureRequestCancellation(client)
	if c.endpoint != "" {
		client.Host = c.endpoint
	}
}

// Strict decoding keeps ambiguous or truncated provider documents out of inventory.
type strictResponses struct{ next common.HTTPRequestDispatcher }

func (d strictResponses) Do(request *http.Request) (*http.Response, error) {
	response, err := d.next.Do(request)
	if err != nil || response == nil || request.Method == http.MethodHead || response.StatusCode < 200 || response.StatusCode >= 300 {
		return response, err
	}
	const limit = 32 << 20
	wire, err := io.ReadAll(io.LimitReader(response.Body, limit+1))
	response.Body.Close()
	if err != nil {
		return nil, fmt.Errorf("read OCI response: %w", err)
	}
	if len(wire) > limit {
		return nil, errors.New("OCI response exceeds 32 MiB")
	}
	var value any
	if err := json.Unmarshal(wire, &value); err != nil {
		return nil, fmt.Errorf("invalid OCI response: %w", err)

sdkcli_call.text:
func (c *Client) Call(ctx context.Context, args []string) (data jsontext.Value, handled bool, err error) {
	command, err := Parse(args)
	if err != nil {
		return nil, false, err
	}
	if _, ok := command.Flags["output"]; ok {
		return nil, false, errors.New("OCI --output is fixed to json")
	}
	if _, ok := command.Flags["region"]; ok {
		return nil, false, errors.New("OCI --region is selected by the caller")
	}
	handler, ok := handlers[command.Path]
	if !ok {
		return nil, false, fmt.Errorf("%w: %s", ErrUnsupported, command.Path)
	}
	value, err := handler(ociclient.RequestContext(ctx), c, command)
	if err != nil {
		return nil, true, fmt.Errorf("OCI read failed: %s: %w", command.Path, err)
	}
	if unused := command.unused(); len(unused) > 0 {
		// The read ignored a flag, so its result may be wider than asked
		// for. Report the command as unsupported rather than answer it.
		return nil, false, fmt.Errorf("%w: %s with --%s", ErrUnsupported, command.Path, strings.Join(unused, ", --"))
	}
	data, err = Render(value)
	return data, true, err
}

// Render marshals an SDK value and rewrites member names to the CLI's
// kebab-case. Members of user-keyed maps keep their keys.
func Render(value any) (jsontext.Value, error) {
	wire, err := json.Marshal(value, json.FormatNilSliceAsNull(true))
	if err != nil {
		return nil, fmt.Errorf("encode OCI response: %w", err)
	}
	return kebab(jsontext.Value(wire), false)
}

// userKeyed are SDK members whose object keys are user data, not schema.
var userKeyed = map[string]bool{
	"freeformTags": true, "definedTags": true, "systemTags": true, "metadata": true, "extendedMetadata": true,
	"securityAttributes": true, "schemaData": true, "opcMeta": true, "lockedAttributes": true,
}

// nameKeyed are SDK members keyed by user-defined resource names (an NLB's
// backend sets and listeners, a load balancer's named sets) whose values are
// still schema objects: only the immediate keys are preserved, so a listener's
// default-backend-set-name keeps resolving to its backend set.
var nameKeyed = map[string]bool{
	"backendSets": true, "listeners": true, "certificates": true, "hostnames": true,
	"pathRouteSets": true, "ruleSets": true, "routingPolicies": true, "sslCipherSuites": true,
}

func kebab(value jsontext.Value, preserveKeys bool) (jsontext.Value, error) {
	switch value.Kind() {
	case '{':
		var typed map[string]jsontext.Value
		if err := json.Unmarshal(value, &typed); err != nil {
			return nil, err
		}
		result := make(map[string]jsontext.Value, len(typed))

plan_validate.text:
func (e *Engine) loadPlan(path string) Object {
	p := readJSON(path, 64*1024, "manual region plan")
	p["_source_path"] = Path(must(filepath.Abs(path)))
	return validatePlan(p)
}

func validatePlan(p Object) Object {
	if !eq(p["schema_version"], 2) || catalog.OCIRegion(text(p["cell"])) == "" || p["region"] != catalog.OCIRegion(text(p["cell"])) {
		fail("unexpected manual plan schema, cell, or OCI region")
	}
	names := obj(p["preview_compartment_names"])
	if !exact(names, "control", "network", "workload") {
		fail("manual compartment names must be distinct safe names for control, network, and workload")
	}
	seen := map[string]bool{}
	for _, v := range names {
		if !safeMatch(`[A-Za-z0-9._-]{1,100}`, v) || seen[text(v)] {
			fail("manual compartment names must be distinct safe names for control, network, and workload")
		}
		seen[text(v)] = true
	}
	hosts, ok := p["hosts"].([]any)
	if !ok || len(hosts) == 0 {
		fail("manual plan must define at least one host")
	}
	slots, members := []string{}, []string{}
	controllers := 0
	seen = map[string]bool{}
	for _, v := range hosts {
		h, ok := v.(Object)
		if !ok || seen[text(h["slot"])] {
			fail("manual host slots must be unique objects")
		}
		slot := text(h["slot"])
		seen[slot] = true
		slots = append(slots, slot)
		if strings.HasPrefix(slot, "controller-") {
			controllers++
		} else if strings.HasPrefix(slot, "member-") {
			members = append(members, slot)
		}
	}
	if !eq(controllers, p["controller_replicas"]) || !eq(len(members), p["database_members"]) || controllers+len(members) != len(hosts) {
		fail("manual host roster differs from its controller and database member counts")
	}
	for _, v := range hosts {
		h := obj(v)
		slot := text(h["slot"])
		hostArchitecture(h)
		if !safeMatch(`(?:controller|member)-[a-z][a-z0-9-]{0,30}`, slot) || !safeMatch(`[A-Za-z0-9][A-Za-z0-9.-]{0,99}`, h["shape"]) || number(h["ocpus"]) <= 0 || number(h["memory_gb"]) < number(h["ocpus"]) || number(h["boot_gb"]) < 50 || number(h["data_gb"]) < 0 || (strings.HasPrefix(slot, "controller-") && number(h["data_gb"]) != 0) || (strings.HasPrefix(slot, "member-") && number(h["data_gb"]) <= 0) {
			fail("unexpected manual shape or size for " + slot)
		}
	}
	network, nok := prefix(p["network_cidr"])
	subnet, sok := prefix(p["subnet_cidr"])
	if !nok || !sok || !privatePrefix(network) || !privatePrefix(subnet) || !within(p["subnet_cidr"], network) {
		fail("manual VCN and subnet must be nested private CIDRs")
	}
	if err := networkplan.ValidateRegion(text(p["cell"]), text(p["network_cidr"])); err != nil {
		fail(err.Error())
	}
	seen = map[string]bool{}
	for _, v := range hosts {
		ip := text(obj(v)["private_ip"])
		a, err := netip.ParseAddr(ip)
		if err != nil || seen[ip] || !subnet.Contains(a) {
			fail("manual host addresses must be unique and inside the private subnet")
		}
		seen[ip] = true
	}
	ids := obj(p["resource_ids"])
	fields := append(keysAny(resourceKinds), "instances", "boot_volumes", "data_volumes")
	if !exact(ids, fields...) {
		fail("manual plan must bind the exact foundation and host resource ID map")
	}
	for _, key := range fields {
		kind, ok := resourceKinds[key]
		if !ok || ids[key] == nil {
			continue
		}
		if key == "network_load_balancer" && l7Public(p) {
			kind = "loadbalancer"
		}
		region := text(p["region"])
		if kind == "compartment" || kind == "policy" || kind == "dynamicgroup" {
			region = ""
		}
		requireOCID(ids[key], kind, region)
	}
	for _, key := range []string{"instances", "boot_volumes", "data_volumes"} {
		expected := slots
		kind := "instance"
		if key == "boot_volumes" {
			kind = "bootvolume"
		}
		if key == "data_volumes" {
			kind = "volume"
			expected = members
		}
		if !exact(ids[key], expected...) {
			fail("manual " + key + " must map every planned slot to an exact OCID or null")
		}
		seen = map[string]bool{}
		for _, id := range obj(ids[key]) {
			if id == nil {
				continue
			}
			requireOCID(id, kind, text(p["region"]))
			if seen[text(id)] {
				fail("manual " + key + " OCIDs must be unique")
			}
			seen[text(id)] = true
		}
	}
	if p["seed_a_create_identity"] != nil && !safeMatch(`[A-Za-z0-9][A-Za-z0-9._~-]{0,127}`, p["seed_a_create_identity"]) {
		fail("manual seed-A create identity is invalid")
	}
	b := obj(p["budget"])
	if !contains([]string{"USD", "BRL"}, b["currency"]) || number(b["monthly_limit"]) <= 0 {
		fail("monthly budget must be finite and positive in USD or BRL")
	}
	if !eq(b["replacement_hosts_max"], 1) || number(b["replacement_overlap_hours_max"]) > 72 {
		fail("replacement allowance exceeds the bounded plan")
	}
	if number(b["snapshot_gb_max"]) > 350 || number(b["object_storage_gb_max"]) < 0 || number(b["object_storage_gb_max"]) > 10 || number(b["staging_object_storage_gb_max"]) < 0 || number(b["staging_object_storage_gb_max"]) > 10 {
		fail("storage allowance exceeds the bounded plan")
	}
	if baseline, present := p["existing_operations_host"]; present {
		existing := obj(baseline)
		if !exact(existing, "instance_id", "boot_volume_id", "data_volume_id", "public_ip_id", "vcn_id", "internet_gateway_id", "expected_shape", "expected_architecture", "expected_ocpus", "expected_memory_gb", "expected_volume_gb", "expected_volume_vpus_per_gb") {
			fail("manual plan must bind the exact existing operations host baseline")
		}
		if !safeMatch(`[A-Za-z0-9][A-Za-z0-9.-]{0,99}`, existing["expected_shape"]) {
			fail("manual operations host must declare its exact expected shape")
		}
		hostArchitecture(Object{"architecture": existing["expected_architecture"]})
		for key, kind := range map[string]string{"instance_id": "instance", "boot_volume_id": "bootvolume", "data_volume_id": "volume", "public_ip_id": "publicip", "vcn_id": "vcn", "internet_gateway_id": "internetgateway"} {
			requireOCID(existing[key], kind, "")
		}
		if !eq(existing["expected_volume_gb"], 50) || !eq(existing["expected_volume_vpus_per_gb"], 10) {
			fail("existing operations host data volume differs from the bounded cost model")
		}
	}
	gateway := validateGateway(p, network)
	if ids["local_peering_gateway"] != nil && gateway == nil {
		fail("manual cell peering gateway requires a declared operator gateway")
	}
	public := validatePublic(p, network, subnet)
	if public == nil {
		for key := range publicIDs {
			if ids[key] != nil {
				fail("manual public API resources require a declared public API")
			}
		}
	}
	sec := obj(p["network_security"])
	if !exact(sec, "nsg_rules", "workload_nsg_rules", "security_list_ingress_rules", "security_list_egress_rules", "route_rules", "service_gateway_service_id", "service_gateway_cidr_block") {
		fail("manual plan must declare exact network and security state")
	}
	for _, key := range append(append([]string{}, ingressLists...), "security_list_egress_rules") {
		validateRules(sec[key], key)
	}
	validateBoundary(sec, network, gateway, public)
	routes, ok := sec["route_rules"].([]any)
	if !ok {
		fail("manual plan route_rules must declare exact destination, type, and target triples")
	}
	for _, v := range routes {
		if !exact(v, "destination", "destination_type", "network_entity_id") {
			fail("manual plan route_rules must declare exact destination, type, and target triples")
		}
		for _, x := range obj(v) {
			if text(x) == "" {
				fail("manual plan route_rules must declare exact destination, type, and target triples")
			}
		}
	}
	service, cidr := sec["service_gateway_service_id"], sec["service_gateway_cidr_block"]
	if (service == nil) != (cidr == nil) {
		fail("manual service gateway ID and service CIDR must be configured together")
	}
	if service != nil {
		requireOCID(service, "service", text(p["region"]))
		expected := []any{Object{"destination": cidr, "destination_type": "SERVICE_CIDR_BLOCK", "network_entity_id": "{service_gateway_id}"}}
		if gateway != nil {
			expected = append(expected, Object{"destination": text(gateway["private_ip"]) + "/32", "destination_type": "CIDR_BLOCK", "network_entity_id": "{local_peering_gateway_id}"})
		}
		if !eq(routes, expected) {
			fail("manual routes must be the exact service gateway route and operator gateway /32 peering route")
		}
	} else if ids["service_gateway"] != nil || ids["route_table"] != nil || len(routes) > 0 || gateway != nil {
		fail("manual plan has route resources without a service gateway declaration")
	}
	identity := obj(p["identity"])
	if !exact(identity, "controller_dynamic_group_name", "controller_policy_name", "objectstorage_key_policy_name", "host_dynamic_group_name", "host_policy_name") {
		fail("manual plan must declare exact live controller IAM readiness expectations")
	}
	for k, v := range identity {
		if !safeMatch(`[A-Za-z0-9._-]{1,100}`, v) {
			fail("manual IAM " + k + " is invalid")
		}
	}
	secret := obj(p["host_credential_secret"])
	if !exact(secret, "compartment_id", "secret_id") {
		fail("manual plan must bind the exact host LiveS3Credential secret and compartment")
	}
	if secret["compartment_id"] != nil || secret["secret_id"] != nil {
		requireOCID(secret["compartment_id"], "compartment", "")
		requireOCID(secret["secret_id"], "vaultsecret", text(p["region"]))
	}
	validateNetbird(p, gateway)
	if obj(ids["instances"])["controller-a"] != nil && p["seed_a_create_identity"] == nil {
		fail("manual controller-a OCID requires its preserved seed-A create identity")
	}
	if !integer(p["bucket_retention_days"]) || number(p["bucket_retention_days"]) < 1 || number(p["bucket_retention_days"]) > 3650 {
		fail("manual ledger and backup retention must be a bounded whole-day duration")
	}
	return p
}

read_json.text:
func readBytes(path string, limit int, label string) []byte {
	fd, err := unix.Open(path, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if err != nil {
		fail(label + " is unreadable or invalid JSON")
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	st, err := f.Stat()
	if err != nil {
		fail(label + " is unreadable or invalid JSON")
	}
	if !st.Mode().IsRegular() || st.Size() <= 0 || st.Size() > int64(limit) {
		fail(label + " has invalid size or is not a regular file")
	}
	wire := must(io.ReadAll(io.LimitReader(f, int64(limit+1))))
	if len(wire) == 0 || len(wire) > limit {
		fail(label + " has invalid size")
	}
	return wire
}
func readJSON(path string, limit int, label string) Object {
	wire := readBytes(path, limit, label)
	v, err := decodeJSON(wire)
	if err != nil {
		if strings.Contains(err.Error(), "duplicate") {
			fail("JSON document has duplicate fields")
		}
		fail(label + " is unreadable or invalid JSON")
	}
	m, ok := v.(map[string]any)
	if !ok {
		fail(label + " must be an object")
	}
	return m
}

capture.text:
func capture[T any](fn func() T) (v T, err error) {
	defer func() {
		if r := recover(); r != nil {
			if e, ok := r.(error); ok {
				err = e
			} else {
				err = fmt.Errorf("%v", r)
			}
		}
	}()
	return fn(), nil
}
func ReadJSON(path string, limit int, label string) (Object, error) {
	return capture(func() Object { return readJSON(path, limit, label) })
}

