func GRU() Desired {
	return Desired{
		Cell: "gru-1", Region: "sa-saopaulo-1",
		Groups: []GroupSpec{
			{Name: "operators"},
			{Name: "gru-servers", RenamedFrom: []string{"ts-orch-servers"}},
			{Name: "ops-automation"},
		},
		ServersGroup: "gru-servers",
		Network: NetworkSpec{
			Name: "gru-cell", Description: "TerraScale GRU private cell",
