func (a *issuerAttempt) repository(ctx context.Context) error {
	intent := a.issuer.scope.Intent()
	request := artifacts.ListContainerRepositoriesRequest{CompartmentId: new(intent.RepositoryCompartmentID), DisplayName: new(intent.RepositoryName)}
	found := ""
	for range 32 {
		response, err := a.issuer.artifacts.ListContainerRepositories(ociclient.RequestContext(ctx), request)
		if err != nil {
			return ErrIssuer
		}
		for _, repo := range response.Items {
			if text(repo.DisplayName) != intent.RepositoryName || text(repo.CompartmentId) != intent.RepositoryCompartmentID || !strings.HasPrefix(text(repo.Id), "ocid1.containerrepo.") ||
				repo.IsPublic == nil || *repo.IsPublic ||
				repo.LifecycleState != artifacts.ContainerRepositoryLifecycleStateAvailable || found != "" {
				return ErrIssuer
			}
			found = text(repo.Id)
		}
		if response.OpcNextPage == nil {
			if found == "" || a.state.RepositoryID != "" && a.state.RepositoryID != found {
				return ErrIssuer
			}
			observed, err := a.issuer.artifacts.GetContainerRepository(ociclient.RequestContext(ctx), artifacts.GetContainerRepositoryRequest{RepositoryId: new(found)})
			if err != nil || text(observed.Id) != found || text(observed.CompartmentId) != intent.RepositoryCompartmentID || text(observed.DisplayName) != intent.RepositoryName ||
				observed.IsPublic == nil || *observed.IsPublic || observed.IsImmutable == nil || !*observed.IsImmutable || observed.LifecycleState != artifacts.ContainerRepositoryLifecycleStateAvailable {
				return ErrIssuer
			}
			a.state.RepositoryID = found
			return a.save(ctx, true)
		}
		request.Page = response.OpcNextPage
	}
	return ErrIssuer
}

func (a *issuerAttempt) retry(step string) string {
	sum := sha256.Sum256([]byte(a.state.OperationID + "\x00" + step))
	return hex.EncodeToString(sum[:])
}

func (a *issuerAttempt) tags() map[string]string {
	return map[string]string{"terrascale-issuer-operation": a.state.OperationID, "terrascale-installation": a.issuer.scope.InstallationID()}
}

func (a *issuerAttempt) owned(tags map[string]string) bool {
	for k, v := range a.tags() {
		if tags[k] != v {
			return false
		}
	}
	return true
}

func (a *issuerAttempt) statement() string {
	intent := a.issuer.scope.Intent()
	return "Allow group id " + a.state.GroupID + " to read repos in compartment id " + intent.RepositoryCompartmentID + " where target.repo.name = '" + intent.RepositoryName + "'"
}

func (a *issuerAttempt) ensureIdentity(ctx context.Context) (identity.User, error) {
	i := a.issuer
	intent := i.scope.Intent()
	var user identity.User
	if a.state.UserID == "" {
		// OCI's persisted request token, never a mutable name/tag match, recovers creation.
		err := a.call(ctx, true, func(ctx context.Context) error {
			response, err := i.identity.CreateUser(ctx, identity.CreateUserRequest{CompartmentId: new(i.scope.TenancyID()), Name: new(intent.PrincipalName), Email: new(intent.PrincipalEmail), Description: new("TerraScale OCIR pull identity"), FreeformTags: a.tags(), OpcRetryToken: new(a.retry("user"))})
			user = response.User
			return err
		})
		if err != nil {
			return identity.User{}, err
		}
		if !strings.HasPrefix(text(user.Id), "ocid1.user.") || text(user.Name) != intent.PrincipalName || text(user.CompartmentId) != i.scope.TenancyID() || !a.owned(user.FreeformTags) {
			return identity.User{}, ErrIssuer
		}
		a.state.UserID = text(user.Id)
		if err := a.save(ctx, true); err != nil {
			return identity.User{}, err
		}
	}
	response, err := i.identity.GetUser(ociclient.RequestContext(ctx), identity.GetUserRequest{UserId: new(a.state.UserID)})
	if err != nil {
		return identity.User{}, ErrIssuer
	}
	user = response.User
	if text(user.Id) != a.state.UserID || text(user.Name) != intent.PrincipalName || text(user.Email) != intent.PrincipalEmail ||
		text(user.CompartmentId) != i.scope.TenancyID() || user.LifecycleState != identity.UserLifecycleStateActive ||
		user.IdentityProviderId != nil || user.ExternalIdentifier != nil || !a.owned(user.FreeformTags) {
		return identity.User{}, ErrIssuer
	}
	if !pullCapabilities(user.Capabilities) {
		if response.Etag == nil || text(response.Etag) == "" {
			return identity.User{}, ErrIssuer
		}
		if err := a.call(ctx, true, func(ctx context.Context) error {
			_, err := i.identity.UpdateUserCapabilities(ctx, identity.UpdateUserCapabilitiesRequest{UserId: new(a.state.UserID), IfMatch: response.Etag,
				CanUseConsolePassword: new(false), CanUseApiKeys: new(false), CanUseAuthTokens: new(true), CanUseSmtpCredentials: new(false), CanUseDBCredentials: new(false), CanUseCustomerSecretKeys: new(false), CanUseOAuth2ClientCredentials: new(false)})
			return err
		}); err != nil {
			return identity.User{}, err
		}
		response, err = i.identity.GetUser(ociclient.RequestContext(ctx), identity.GetUserRequest{UserId: new(a.state.UserID)})
		if err != nil || !pullCapabilities(response.Capabilities) {
			return identity.User{}, ErrIssuer
		}
	}
	if a.state.GroupID == "" {
		var group identity.Group
		if err := a.call(ctx, true, func(ctx context.Context) error {
			response, err := i.identity.CreateGroup(ctx, identity.CreateGroupRequest{CompartmentId: new(i.scope.TenancyID()), Name: new(intent.PrincipalName + "-pull"), Description: new("TerraScale exact repository readers"), FreeformTags: a.tags(), OpcRetryToken: new(a.retry("group"))})
			group = response.Group
			return err
		}); err != nil {
			return identity.User{}, err
		}
		if !strings.HasPrefix(text(group.Id), "ocid1.group.") || text(group.Name) != intent.PrincipalName+"-pull" || text(group.CompartmentId) != i.scope.TenancyID() || !a.owned(group.FreeformTags) {
			return identity.User{}, ErrIssuer
		}
		a.state.GroupID = text(group.Id)
		if err := a.save(ctx, true); err != nil {
			return identity.User{}, err
		}
	}
	group, err := i.identity.GetGroup(ociclient.RequestContext(ctx), identity.GetGroupRequest{GroupId: new(a.state.GroupID)})
	if err != nil || text(group.Id) != a.state.GroupID || text(group.Name) != intent.PrincipalName+"-pull" || text(group.CompartmentId) != i.scope.TenancyID() || group.LifecycleState != identity.GroupLifecycleStateActive || !a.owned(group.FreeformTags) {
		return identity.User{}, ErrIssuer
	}
	if a.state.PolicyID == "" {
		var policy identity.Policy
		if err := a.call(ctx, true, func(ctx context.Context) error {
			response, err := i.identity.CreatePolicy(ctx, identity.CreatePolicyRequest{CompartmentId: new(intent.RepositoryCompartmentID), Name: new(intent.PrincipalName + "-pull"), Description: new("TerraScale read only one OCIR repository"), Statements: []string{a.statement()}, FreeformTags: a.tags(), OpcRetryToken: new(a.retry("policy"))})
			policy = response.Policy
			return err
		}); err != nil {
			return identity.User{}, err
		}
		if !strings.HasPrefix(text(policy.Id), "ocid1.policy.") || !a.validPolicy(policy) {
			return identity.User{}, ErrIssuer
		}
		a.state.PolicyID = text(policy.Id)
		if err := a.save(ctx, true); err != nil {
			return identity.User{}, err
		}
	}
	policy, err := i.identity.GetPolicy(ociclient.RequestContext(ctx), identity.GetPolicyRequest{PolicyId: new(a.state.PolicyID)})
	if err != nil || text(policy.Id) != a.state.PolicyID || !a.validPolicy(policy.Policy) || policy.LifecycleState != identity.PolicyLifecycleStateActive {
		return identity.User{}, ErrIssuer
	}
	if err := a.membership(ctx); err != nil {
		return identity.User{}, err
	}
	return user, nil
}

func (a *issuerAttempt) validPolicy(policy identity.Policy) bool {
	intent := a.issuer.scope.Intent()
	return text(policy.CompartmentId) == intent.RepositoryCompartmentID && text(policy.Name) == intent.PrincipalName+"-pull" && slices.Equal(policy.Statements, []string{a.statement()}) && a.owned(policy.FreeformTags)
}

func pullCapabilities(c *identity.UserCapabilities) bool {
	return c != nil && c.CanUseAuthTokens != nil && *c.CanUseAuthTokens &&
		c.CanUseConsolePassword != nil && !*c.CanUseConsolePassword && c.CanUseApiKeys != nil && !*c.CanUseApiKeys &&
		c.CanUseSmtpCredentials != nil && !*c.CanUseSmtpCredentials && c.CanUseDbCredentials != nil && !*c.CanUseDbCredentials &&
		c.CanUseCustomerSecretKeys != nil && !*c.CanUseCustomerSecretKeys && c.CanUseOAuth2ClientCredentials != nil && !*c.CanUseOAuth2ClientCredentials
}

func (a *issuerAttempt) membership(ctx context.Context) error {
	// A dedicated user must not acquire another group's permissions.
	request := identity.ListUserGroupMembershipsRequest{CompartmentId: new(a.issuer.scope.TenancyID()), UserId: new(a.state.UserID)}
	found := ""
	for range 32 {
		response, err := a.issuer.identity.ListUserGroupMemberships(ociclient.RequestContext(ctx), request)
		if err != nil {
			return ErrIssuer
		}
		for _, membership := range response.Items {
			if text(membership.UserId) != a.state.UserID || text(membership.GroupId) != a.state.GroupID || text(membership.CompartmentId) != a.issuer.scope.TenancyID() ||
				membership.LifecycleState != identity.UserGroupMembershipLifecycleStateActive || text(membership.Id) == "" || found != "" {
				return ErrIssuer
			}
			found = text(membership.Id)
		}
		if response.OpcNextPage == nil {
			if found != "" {
				if a.state.MembershipID != "" && a.state.MembershipID != found {
					return ErrIssuer
				}
				a.state.MembershipID = found
				return a.save(ctx, true)
			}
			if a.state.MembershipID != "" {
				return ErrIssuer
			}
			if err := a.call(ctx, true, func(ctx context.Context) error {
				response, err := a.issuer.identity.AddUserToGroup(ctx, identity.AddUserToGroupRequest{UserId: new(a.state.UserID), GroupId: new(a.state.GroupID)})
				if err == nil && text(response.UserId) == a.state.UserID && text(response.GroupId) == a.state.GroupID && text(response.Id) != "" {
					a.state.MembershipID = text(response.Id)
				} else if err == nil {
					return ErrIssuer
				}
				return err
			}); err != nil {
				return err
			}
			return a.save(ctx, true)
		}
		request.Page = response.OpcNextPage
	}
	return ErrIssuer
}

issuer_token.text:
func credentialHash(value string) string {
	sum := sha256.Sum256([]byte(value))
	return hex.EncodeToString(sum[:])
}

func (a *issuerAttempt) ref() vaultsecret.Ref {
	intent := a.issuer.scope.Intent()
	return vaultsecret.Ref{Vault: intent.VaultTarget.VaultID, Name: intent.SecretName}
}

func (a *issuerAttempt) tokens(ctx context.Context) ([]identity.AuthToken, error) {
	response, err := a.issuer.identity.ListAuthTokens(ociclient.RequestContext(ctx), identity.ListAuthTokensRequest{UserId: new(a.state.UserID)})
	if err != nil || response.OpcNextPage != nil || len(response.Items) > 2 {
		return nil, ErrIssuer
	}
	for _, token := range response.Items {
		if !strings.HasPrefix(text(token.Id), "ocid1.credential.") || text(token.UserId) != a.state.UserID || token.TimeCreated == nil ||
			token.LifecycleState != identity.AuthTokenLifecycleStateActive && token.LifecycleState != identity.AuthTokenLifecycleStateCreating {
			return nil, ErrIssuer
		}
	}
	return response.Items, nil
}

func (a *issuerAttempt) ensureCredential(ctx context.Context, user identity.User) error {
	if err := a.check(ctx); err != nil {
		return err
	}
	current, readErr := vaultsecret.ReadCurrent(ociclient.RequestContext(ctx), a.issuer.secrets, a.ref())
	if a.state.Stage == "vault-pending" {
		if readErr == nil && a.state.PendingHash != "" && credentialHash(current.Value()) == a.state.PendingHash &&
			(a.state.SecretID == "" || current.ID == a.state.SecretID) && current.Version > a.state.Version {
			if err := a.published(ctx, current); err != nil {
				return err
			}
		} else {
			// Bytes were lost before publication was confirmed. Revoke that exact
			// token before clearing its operation, even if Vault later converges.
			if a.state.TokenID == "" {
				return ErrIssuer
			}
			if err := a.revoke(ctx, a.state.TokenID); err != nil {
				return err
			}
			a.state.TokenID = a.state.PriorTokenID
			a.state.PriorTokenID = ""
			a.state.Stage = "ready"
			a.state.TokenOperation = ""
			a.state.PendingHash = ""
			if err := a.save(ctx, true); err != nil {
				return err
			}
			// Reread after revocation, never reuse an earlier observation.
			current, readErr = vaultsecret.ReadCurrent(ociclient.RequestContext(ctx), a.issuer.secrets, a.ref())
		}
	}
	if a.state.PriorTokenID != "" && a.state.Stage == "ready" {
		if err := a.activeToken(ctx); err != nil {
			return err
		}
		if err := a.revoke(ctx, a.state.PriorTokenID); err != nil {
			return err
		}
		a.state.PriorTokenID = ""
		if err := a.save(ctx, true); err != nil {
			return err
		}
	}
	if a.state.Stage == "ready" && a.state.Hash != "" {
		if readErr != nil || current.ID != a.state.SecretID || current.Version != a.state.Version || credentialHash(current.Value()) != a.state.Hash {
			return ErrIssuer
		}
		scope := PullScope{RegistryHost: a.issuer.host, Repository: a.issuer.scope.Intent().RegistryNamespace + "/" + a.issuer.scope.Intent().RepositoryName}
		credential, err := decodePull(current.Value(), scope)
		if err != nil || credential.username != a.issuer.scope.Intent().RegistryNamespace+"/"+text(user.Name) {
			return ErrIssuer
		}
		tokens, err := a.tokens(ctx)
		if err != nil {
			return err
		}
		valid := false
		for _, token := range tokens {
			if text(token.Id) != a.state.TokenID {
				return ErrIssuer
			}
			valid = token.LifecycleState == identity.AuthTokenLifecycleStateActive && (token.TimeExpires == nil || time.Now().Before(token.TimeExpires.Time))
		}
		if !valid {
			return ErrIssuer
		}
		if time.Since(a.state.PublishedAt) < tokenRotation {
			return nil
		}
	}
	if a.state.TokenOperation == "" {
		if readErr != nil && !vaultsecret.Absent(readErr) {
			return ErrIssuer
		}
		// An existing unrecorded Vault value cannot be adopted or overwritten.
		if readErr == nil && a.state.SecretID == "" {
			return ErrIssuer
		}
		tokens, err := a.tokens(ctx)
		if err != nil {
			return err
		}
		before := make([]string, 0, len(tokens))
		for _, token := range tokens {
			if text(token.Id) != a.state.TokenID || a.state.TokenID == "" {
				return ErrIssuer
			}
			before = append(before, text(token.Id))
		}
		a.state.BeforeTokens = before
		a.state.TokenOperation = uuid.New().String()
		a.state.TokenStarted = time.Now().UTC()
		a.state.TokenExpires = a.state.TokenStarted.Add(90 * time.Second)
		if deadline, ok := ctx.Deadline(); ok && deadline.Before(a.state.TokenExpires) {
			a.state.TokenExpires = deadline.UTC()
		}
		if expiry := a.issuer.scope.ExpiresAt(); expiry.Before(a.state.TokenExpires) {
			a.state.TokenExpires = expiry.UTC()
		}
		a.state.Stage = "token-pending"
		if err := a.save(ctx, true); err != nil {
			return err
		}
	}
	if a.state.Stage != "token-pending" {
		return ErrIssuer
	}
	return a.issue(ctx, user)
}

func (a *issuerAttempt) issue(ctx context.Context, user identity.User) error {
	var token identity.AuthToken
	// Even an explicit later replay uses the durable same-operation token.
	var err error
	if time.Now().Before(a.state.TokenExpires) {
		original, cancel := context.WithDeadline(ctx, a.state.TokenExpires)
		err = a.call(original, true, func(ctx context.Context) error {
			response, err := a.issuer.identity.CreateAuthToken(ctx, identity.CreateAuthTokenRequest{
				UserId: new(a.state.UserID), Description: new("terrascale-ocir:" + a.state.TokenOperation), OpcRetryToken: new(a.state.TokenOperation),
				RequestMetadata: common.RequestMetadata{RetryPolicy: new(common.NoRetryPolicy())}})
			token = response.AuthToken
			return err
		})
		cancel()
	} else {
		err = ErrIssuer
	}
	if err != nil || text(token.Token) == "" {
		// Exact pending operation + pre-request inventory are required before
		// revoking an observed lost-value token. Description alone is not proof.
		tokens, listErr := a.tokens(ctx)
		if listErr != nil {
			return ErrIssuer
		}
		candidate := ""
		for _, observed := range tokens {
			if slices.Contains(a.state.BeforeTokens, text(observed.Id)) {
				continue
			}
			if candidate != "" || text(observed.Description) != "terrascale-ocir:"+a.state.TokenOperation || observed.TimeCreated.Time.Before(a.state.TokenStarted.Add(-time.Second)) {
				return ErrIssuer
			}
			candidate = text(observed.Id)
		}
		if candidate == "" {
			return ErrIssuer
		}
		// Persist the exact recovered OCID before any delete or fresh issuance.
		a.state.PriorTokenID = a.state.TokenID
		a.state.TokenID = candidate
		a.state.Stage = "vault-pending"
		if err := a.save(ctx, true); err != nil {
			return err
		}
		return ErrIssuer
	}
	if !strings.HasPrefix(text(token.Id), "ocid1.credential.") || text(token.UserId) != a.state.UserID ||
		text(token.Description) != "terrascale-ocir:"+a.state.TokenOperation || token.TimeCreated == nil || token.TimeCreated.Time.Before(a.state.TokenStarted.Add(-time.Second)) ||
		slices.Contains(a.state.BeforeTokens, text(token.Id)) {
		return ErrIssuer
	}
	value, err := json.Marshal(struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}{a.issuer.scope.Intent().RegistryNamespace + "/" + text(user.Name), text(token.Token)})
	if err != nil {
		return ErrIssuer
	}
	a.state.PriorTokenID = a.state.TokenID
	a.state.TokenID = text(token.Id)
	a.state.PendingHash = credentialHash(string(value))
	a.state.Stage = "vault-pending"
	if err := a.save(ctx, true); err != nil {
		return err
	}
	// Never persist value or include provider errors that may echo request bytes.
	if err := a.call(ctx, false, func(ctx context.Context) error {
		if a.state.SecretID == "" {
			_, err := vaultsecret.Ensure(ctx, a.issuer.vault, a.issuer.scope.Intent().VaultTarget, a.ref().Name, "TerraScale exact repository pull credential", func(context.Context) (string, error) { return string(value), nil })
			return err
		}
		_, err := vaultsecret.PublishVersion(ctx, a.issuer.vault, a.ref(), a.state.SecretID, a.state.Version, value)
		return err
	}); err != nil {
		return err
	}
	current, err := vaultsecret.ReadCurrent(ociclient.RequestContext(ctx), a.issuer.secrets, a.ref())
	if err != nil || credentialHash(current.Value()) != a.state.PendingHash || a.state.SecretID != "" && current.ID != a.state.SecretID || current.Version <= a.state.Version {
		return ErrIssuer
	}
	if err := a.published(ctx, current); err != nil {
		return err
	}
	if err := a.activeToken(ctx); err != nil {
		return err
	}
	if a.state.PriorTokenID != "" {
		if err := a.revoke(ctx, a.state.PriorTokenID); err != nil {
			return err
		}
		a.state.PriorTokenID = ""
		return a.save(ctx, true)
	}
	return nil
}

func (a *issuerAttempt) activeToken(ctx context.Context) error {
	tokens, err := a.tokens(ctx)
	if err != nil {
		return err
	}
	found := false
	for _, token := range tokens {
		if text(token.Id) == a.state.PriorTokenID {
			continue
		}
		if text(token.Id) != a.state.TokenID {
			return ErrIssuer
		}
		found = token.LifecycleState == identity.AuthTokenLifecycleStateActive && (token.TimeExpires == nil || time.Now().Before(token.TimeExpires.Time))
	}
	if !found {
		return ErrIssuer
	}
	return nil
}

func (a *issuerAttempt) published(ctx context.Context, current vaultsecret.Current) error {
	a.state.SecretID, a.state.Version, a.state.Hash = current.ID, current.Version, a.state.PendingHash
	a.state.PendingHash, a.state.TokenOperation = "", ""
	a.state.BeforeTokens = nil
	a.state.PublishedAt = time.Now().UTC()
	a.state.Stage = "ready"
	return a.save(ctx, true)
}

func (a *issuerAttempt) revoke(ctx context.Context, id string) error {
	tokens, err := a.tokens(ctx)
	if err != nil {
		return err
	}
	for _, token := range tokens {
		if text(token.Id) != id {
			continue
		}
		if err := a.call(ctx, true, func(ctx context.Context) error {
			_, err := a.issuer.identity.DeleteAuthToken(ctx, identity.DeleteAuthTokenRequest{UserId: new(a.state.UserID), AuthTokenId: new(id)})
			return err
		}); err != nil {
			return err
		}
	}
	tokens, err = a.tokens(ctx)
	if err != nil {
		return err
	}
	for _, token := range tokens {
		if text(token.Id) == id {
			return ErrIssuer
		}
	}
	return nil
}

